dataTableFormat:
{
    "data convert": [
        {
            "type": "raw",
            "field name": "Ensembl ID",
            "raw field": "ENSG ID"
        },
        {
            "type": "raw",
            "field name": "Symbol",
            "raw field": "Symbol"
        },
        {
            "type": "raw",
            "field name": "Gene name",
            "raw field": "byor_gene"
        },
        {
            "type": "raw",
            "field name": "Entrez Gene ID",
            "raw field": "enstrezID"
        },
        {
            "type": "join multi",
            "field name": "Coding sequence",
            "fields to join": ["chr", "start", "end"],
            "join by": [":",","]
        },
        {
            "type": "replace characters",
            "field name": "Strand",
            "raw field": "strand",
            "replace": [{
                "from": "1",
                "to": "+"
            }]
        },
        {
            "type": "raw",
            "field name": "Locus number",
            "raw field": "Locus"
        },
        {
            "type": "raw",
            "field name": "Classification",
            "raw field": "Label"
        },
        {
            "type": "raw",
            "field name": "High-confidence prioritized gene",
            "raw field": "HCP"
        },
        {
            "type": "raw",
            "field name": "No. deleterious coding SNPs in credible set",
            "raw field": "cred.DC"
        },
        {
            "type": "raw",
            "field name": "Maximum CADD score of deleterious coding SNPs in credible set",
            "raw field": "cred.DC.maxCADD"
        },
        {
            "type": "raw",
            "field name": "Maximum posterior inclusion probability of deleterious coding SNPs in credible set",
            "raw field": "cred.DC.maxPIP"
        },
        {
            "type": "raw",
            "field name": "Minimum GWAS p-value of deleterious coding SNPs in credible set",
            "raw field": "cred.DC.minP"
        },
        {
            "type": "raw",
            "field name": "Minimum GWAS p-value of deleterious coding SNPs in credible set",
            "raw field": "cred.DC.minP"
        },
        {
            "type": "raw",
            "field name": "No. credible set SNPs colocalized with eQTLs",
            "raw field": "cred.eQTL"
        },
        {
            "type": "replace characters",
            "field name": "Sources and tissue types for eQTLs colocalized with credible set SNPs",
            "raw field": "cred.eQTL.ts",
            "replace": [{
                "from": ":",
                "to": "; "
            }]
        },
        {
            "type": "raw",
            "field name": "Maximum posterior inclusion probability of SNPs that colocalize with eQTLs",
            "raw field": "cred.eQTL.maxPIP"
        },
        {
            "type": "raw",
            "field name": "Minimum GWAS p-value of SNPs that colocalize with eQTLs",
            "raw field": "cred.eQTL.minP"
        },
        {
            "type": "raw",
            "field name": "No. credible set SNPs mapped by chromatin interaction mapping",
            "raw field": "cred.CI"
        },
        {
            "type": "replace characters",
            "field name": "Sources and tissue types for chromatin interactions of credible set SNPs",
            "raw field": "cred.CI.ts",
            "replace": [{
                "from": ":",
                "to": "; "
            }]
        },
        {
            "type": "raw",
            "field name": "Maximum posterior inclusion probability of SNPs mapped by chromatin interaction mapping",
            "raw field": "cred.CI.maxPIP"
        },
        {
            "type": "raw",
            "field name": "Minimum GWAS p-value of credible set SNPs mapped by chromatin interaction mapping",
            "raw field": "cred.CI.minP"
        },
        {
            "type": "raw",
            "field name": "No. deleterious coding SNPs in genome-wide significant GWAS SNPs",
            "raw field": "gws.DC"
        },
        {
            "type": "raw",
            "field name": "Maximum CADD score of deleterious coding SNPs in genome-wide significant GWAS SNPs",
            "raw field": "gws.DC.maxCADD"
        },
        {
            "type": "raw",
            "field name": "Minimum GWAS p-value of deleterious coding SNPs in genome-wide significant GWAS SNPs",
            "raw field": "gws.DC.minP"
        },
        {
            "type": "raw",
            "field name": "No. genome-wide significant GWAS SNPs colocalized with eQTLs",
            "raw field": "gws.eQTL"
        },
        {
            "type": "replace characters",
            "field name": "Sources and tissue types for eQTLs colocalized with genome-wide significant GWAS SNPs",
            "raw field": "gws.eQTL.ts",
            "replace": [{
                "from": ":",
                "to": "; "
            }]
        },
        {
            "type": "raw",
            "field name": "Minimum GWAS p-value of genome-wide significant GWAS SNPs that colocalize with eQTLs",
            "raw field": "gws.eQTL.minP"
        },
        {
            "type": "raw",
            "field name": "No. genome-wide significant GWAS SNPs mapped by chromatin interaction mapping",
            "raw field": "gws.CI"
        },
        {
            "type": "replace characters",
            "field name": "Sources and tissue types for chromatin interactions of genome-wide significant GWAS SNPs ",
            "raw field": "gws.CI.ts",
            "replace": [{
                "from": ":",
                "to": "; "
            }]
        },
        {
            "type": "raw",
            "field name": "Minimum GWAS p-value of genome-wide significant GWAS SNPs mapped by chromatin interaction mapping",
            "raw field": "gws.CI.minP"
        }
    ],
    "column formatting": {
        "Ensembl ID": {
            "type": ["link"],
            "link to": "http://useast.ensembl.org/Homo_sapiens/Gene/Summary?g=",
            "new tab": "true"
        },
        "Gene name": {
            "type": ["link"],
            "link to": "https://sleep.hugeamp.org/gene.html?gene=",
            "new tab": "true"
        },
        "Entrez Gene ID": {
            "type": ["link"],
            "link to": "https://www.ncbi.nlm.nih.gov/gene/",
            "new tab": "true"
        }
    },
    "locus field": "Coding sequence",
    "top rows": [
        "Gene name",
        "Entrez Gene ID",
        "Ensembl ID",
        "High-confidence prioritized gene",
        "Classification",
        "Coding sequence",
        "Strand",
        "Locus number"
    ]
}

